from pathlib import Path
import subprocess

ROOT = Path.cwd()
head = subprocess.check_output(['git','rev-parse','--short','HEAD'], text=True).strip()
if not head.startswith('f11ec9e'):
    raise SystemExit(f'Expected HEAD f11ec9e, found {head}. Stop and have ChatGPT re-inspect.')

new_files = {
    'app/(portal)/admin/characters/cosmetic-actions.ts': '"use server";\n\nimport {\n  revalidatePath,\n} from "next/cache";\n\nimport {\n  requireStaffCapability,\n} from "@/lib/auth/require-staff";\nimport {\n  createPremiumFeatureGrantNotification,\n} from "@/lib/premium-features/notifications";\nimport {\n  createAdminClient,\n} from "@/lib/supabase/admin";\n\nconst SOURCES = new Set([\n  "paid",\n  "staff",\n  "reward",\n  "promotion",\n  "gift",\n  "event",\n]);\n\nconst PHASE_ONE_CATEGORIES = new Set([\n  "sheet_frame",\n  "chat_frame",\n]);\n\nfunction required(\n  formData: FormData,\n  key: string,\n) {\n  const value = String(\n    formData.get(key) ?? "",\n  ).trim();\n\n  if (!value) {\n    throw new Error(\n      `${key} is required.`,\n    );\n  }\n\n  return value;\n}\n\nexport async function setCharacterCosmeticEntitlement(\n  formData: FormData,\n) {\n  const staff =\n    await requireStaffCapability(\n      "character_economy",\n    );\n\n  const characterId =\n    required(\n      formData,\n      "characterId",\n    );\n\n  const cosmeticItemId =\n    required(\n      formData,\n      "cosmeticItemId",\n    );\n\n  const enabled =\n    String(\n      formData.get("enabled") ??\n        "false",\n    ) === "true";\n\n  const source = String(\n    formData.get("source") ??\n      "staff",\n  );\n\n  if (!SOURCES.has(source)) {\n    throw new Error(\n      "Invalid cosmetic entitlement source.",\n    );\n  }\n\n  const note =\n    String(\n      formData.get("note") ?? "",\n    )\n      .trim()\n      .slice(0, 1000) || null;\n\n  const admin =\n    createAdminClient();\n\n  const [\n    previousResult,\n    cosmeticResult,\n  ] = await Promise.all([\n    admin\n      .from(\n        "character_cosmetic_entitlements",\n      )\n      .select("enabled")\n      .eq(\n        "character_id",\n        characterId,\n      )\n      .eq(\n        "cosmetic_item_id",\n        cosmeticItemId,\n      )\n      .maybeSingle(),\n\n    admin\n      .from("cosmetic_items")\n      .select(\n        "id, name, category, is_active",\n      )\n      .eq(\n        "id",\n        cosmeticItemId,\n      )\n      .maybeSingle(),\n  ]);\n\n  if (previousResult.error) {\n    throw new Error(\n      `Unable to check existing cosmetic ownership: ${previousResult.error.message}`,\n    );\n  }\n\n  if (\n    cosmeticResult.error ||\n    !cosmeticResult.data\n  ) {\n    throw new Error(\n      `Unable to load cosmetic: ${\n        cosmeticResult.error?.message ??\n        "Cosmetic not found."\n      }`,\n    );\n  }\n\n  const cosmetic =\n    cosmeticResult.data;\n\n  if (\n    !PHASE_ONE_CATEGORIES.has(\n      cosmetic.category,\n    )\n  ) {\n    throw new Error(\n      "Only Phase 1 Sheet Frame and Chat Frame cosmetics can be assigned here.",\n    );\n  }\n\n  if (\n    enabled &&\n    cosmetic.is_active !== true\n  ) {\n    throw new Error(\n      "Inactive cosmetics cannot be granted.",\n    );\n  }\n\n  const wasEnabled =\n    previousResult.data?.enabled ===\n    true;\n\n  const now =\n    new Date().toISOString();\n\n  const { error } = await admin\n    .from(\n      "character_cosmetic_entitlements",\n    )\n    .upsert(\n      {\n        character_id:\n          characterId,\n        cosmetic_item_id:\n          cosmeticItemId,\n        enabled,\n        source,\n        note,\n        granted_at: now,\n        granted_by:\n          staff.userId,\n        updated_at: now,\n      },\n      {\n        onConflict:\n          "character_id,cosmetic_item_id",\n      },\n    );\n\n  if (error) {\n    throw new Error(\n      `Unable to update cosmetic ownership: ${error.message}`,\n    );\n  }\n\n  if (\n    enabled &&\n    !wasEnabled\n  ) {\n    const typeLabel =\n      cosmetic.category ===\n      "sheet_frame"\n        ? "character sheet frame"\n        : "location chat frame";\n\n    try {\n      await createPremiumFeatureGrantNotification({\n        characterId,\n        createdBy:\n          staff.userId,\n        title:\n          `Premium cosmetic unlocked: ${cosmetic.name}`,\n        body:\n          `You have unlocked the ${cosmetic.name} ${typeLabel}. You can equip it from your Cosmetics collection once available.`,\n        href: null,\n      });\n    } catch (\n      notificationError\n    ) {\n      console.error(\n        "Cosmetic ownership was granted, but its notification could not be created:",\n        notificationError,\n      );\n    }\n  }\n\n  revalidatePath(\n    `/admin/characters/${characterId}/premium-features`,\n  );\n  revalidatePath(\n    "/character",\n  );\n  revalidatePath(\n    "/characters",\n  );\n  revalidatePath(\n    "/game",\n  );\n  revalidatePath(\n    "/",\n    "layout",\n  );\n}\n',
    'components/admin/admin-character-cosmetics-access.tsx': 'import {\n  setCharacterCosmeticEntitlement,\n} from "@/app/(portal)/admin/characters/cosmetic-actions";\n\nexport type CharacterCosmeticRow = {\n  id: string;\n  slug: string;\n  name: string;\n  description: string;\n  category:\n    | "sheet_frame"\n    | "chat_frame";\n  preview_image_url:\n    | string\n    | null;\n  asset_url:\n    | string\n    | null;\n  is_active: boolean;\n};\n\nexport type CharacterCosmeticEntitlementRow = {\n  cosmetic_item_id: string;\n  enabled: boolean;\n  source:\n    | "paid"\n    | "staff"\n    | "reward"\n    | "promotion"\n    | "gift"\n    | "event";\n  note: string | null;\n  granted_at: string;\n  granted_by:\n    | string\n    | null;\n  updated_at: string;\n};\n\nfunction categoryLabel(\n  category:\n    CharacterCosmeticRow["category"],\n) {\n  return category ===\n    "sheet_frame"\n    ? "Sheet Frame"\n    : "Location Chat Frame";\n}\n\nexport function AdminCharacterCosmeticsAccess({\n  characterId,\n  cosmetics,\n  entitlements,\n}: {\n  characterId: string;\n  cosmetics:\n    CharacterCosmeticRow[];\n  entitlements:\n    CharacterCosmeticEntitlementRow[];\n}) {\n  const byCosmetic =\n    new Map(\n      entitlements.map(\n        (entry) => [\n          entry.cosmetic_item_id,\n          entry,\n        ],\n      ),\n    );\n\n  return (\n    <section className="mt-6 overflow-hidden border border-[rgb(var(--sep-colour-60482e))]/45 bg-[rgb(var(--sep-colour-15100d))]">\n      <div className="border-b border-[rgb(var(--sep-colour-60482e))]/35 bg-[rgb(var(--sep-colour-100c09))] px-5 py-4">\n        <p className="text-[9px] uppercase tracking-[0.24em] text-[rgb(var(--sep-colour-8c704b))]">\n          Cosmetic access\n        </p>\n\n        <h2 className="mt-2 font-serif text-2xl text-[rgb(var(--sep-colour-e1c89f))]">\n          Premium Cosmetics\n        </h2>\n\n        <p className="mt-2 max-w-3xl text-[11px] leading-5 text-[rgb(var(--sep-colour-8f8271))]">\n          Grant or revoke\n          collectible visual\n          cosmetics. Revoking an\n          equipped cosmetic\n          automatically unequips it.\n        </p>\n      </div>\n\n      <div className="grid gap-px bg-[rgb(var(--sep-colour-4f3b28))]/35 lg:grid-cols-2">\n        {cosmetics.map(\n          (cosmetic) => {\n            const entitlement =\n              byCosmetic.get(\n                cosmetic.id,\n              );\n\n            const enabled =\n              entitlement?.enabled ===\n              true;\n\n            return (\n              <form\n                key={cosmetic.id}\n                id={`premium-feature-cosmetic-${cosmetic.id}`}\n                data-admin-premium-feature="true"\n                data-admin-feature-name={cosmetic.name}\n                data-admin-feature-type={`Cosmetic · ${categoryLabel(cosmetic.category)}`}\n                action={setCharacterCosmeticEntitlement}\n                className="scroll-mt-6 bg-[rgb(var(--sep-colour-17110d))] p-5"\n              >\n                <input\n                  type="hidden"\n                  name="characterId"\n                  value={characterId}\n                />\n\n                <input\n                  type="hidden"\n                  name="cosmeticItemId"\n                  value={cosmetic.id}\n                />\n\n                <div className="flex items-start gap-4">\n                  <div className="flex h-20 w-20 shrink-0 items-center justify-center overflow-hidden border border-[rgb(var(--sep-colour-59432c))]/45 bg-[rgb(var(--sep-colour-0d0907))] p-2">\n                    {cosmetic.preview_image_url ??\n                    cosmetic.asset_url ? (\n                      <img\n                        src={\n                          cosmetic.preview_image_url ??\n                          cosmetic.asset_url ??\n                          ""\n                        }\n                        alt=""\n                        className="max-h-full max-w-full object-contain"\n                      />\n                    ) : (\n                      <span className="text-center text-[7px] uppercase tracking-[0.12em] text-[rgb(var(--sep-colour-625747))]">\n                        No preview\n                      </span>\n                    )}\n                  </div>\n\n                  <div className="min-w-0 flex-1">\n                    <div className="flex items-start justify-between gap-4">\n                      <div className="min-w-0">\n                        <p className="mb-1 text-[7px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-806b50))]">\n                          {categoryLabel(\n                            cosmetic.category,\n                          )}\n                        </p>\n\n                        <h3 className="font-serif text-lg text-[rgb(var(--sep-colour-dfc79c))]">\n                          {cosmetic.name}\n                        </h3>\n                      </div>\n\n                      <span\n                        className={\n                          enabled\n                            ? "shrink-0 border border-[rgb(var(--sep-colour-668657))] bg-[rgb(var(--sep-colour-172313))] px-2 py-1 text-[8px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-a8cf92))]"\n                            : "shrink-0 border border-[rgb(var(--sep-colour-65483e))] bg-[rgb(var(--sep-colour-221512))] px-2 py-1 text-[8px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-b78378))]"\n                        }\n                      >\n                        {enabled\n                          ? "Enabled"\n                          : "Disabled"}\n                      </span>\n                    </div>\n\n                    <p className="mt-2 text-[11px] leading-5 text-[rgb(var(--sep-colour-8f8271))]">\n                      {cosmetic.description ||\n                        "Collectible Sepulchria cosmetic."}\n                    </p>\n                  </div>\n                </div>\n\n                <div className="mt-5 grid gap-4">\n                  <label>\n                    <span className="text-[8px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-806b50))]">\n                      Access\n                    </span>\n\n                    <select\n                      name="enabled"\n                      defaultValue={\n                        enabled\n                          ? "true"\n                          : "false"\n                      }\n                      className="mt-2 w-full border border-[rgb(var(--sep-colour-60482e))]/55 bg-[rgb(var(--sep-colour-0d0907))] px-3 py-2.5 text-sm text-[rgb(var(--sep-colour-d7c4a5))]"\n                    >\n                      <option value="false">\n                        Disabled\n                      </option>\n\n                      <option value="true">\n                        Enabled\n                      </option>\n                    </select>\n                  </label>\n\n                  <label>\n                    <span className="text-[8px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-806b50))]">\n                      Unlock source\n                    </span>\n\n                    <select\n                      name="source"\n                      defaultValue={\n                        entitlement?.source ??\n                        "staff"\n                      }\n                      className="mt-2 w-full border border-[rgb(var(--sep-colour-60482e))]/55 bg-[rgb(var(--sep-colour-0d0907))] px-3 py-2.5 text-sm text-[rgb(var(--sep-colour-d7c4a5))]"\n                    >\n                      <option value="paid">\n                        Real-money purchase\n                      </option>\n                      <option value="staff">\n                        Staff grant\n                      </option>\n                      <option value="reward">\n                        Reward\n                      </option>\n                      <option value="promotion">\n                        Promotion\n                      </option>\n                      <option value="gift">\n                        Gift\n                      </option>\n                      <option value="event">\n                        Event\n                      </option>\n                    </select>\n                  </label>\n\n                  <label>\n                    <span className="text-[8px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-806b50))]">\n                      Staff note\n                    </span>\n\n                    <textarea\n                      name="note"\n                      rows={3}\n                      maxLength={1000}\n                      defaultValue={\n                        entitlement?.note ??\n                        ""\n                      }\n                      placeholder="Optional: purchase reference, reward reason, event prize..."\n                      className="mt-2 w-full resize-y border border-[rgb(var(--sep-colour-60482e))]/55 bg-[rgb(var(--sep-colour-0d0907))] px-3 py-2.5 text-sm leading-6 text-[rgb(var(--sep-colour-d7c4a5))]"\n                    />\n                  </label>\n                </div>\n\n                <div className="mt-5 flex justify-end border-t border-[rgb(var(--sep-colour-5d452d))]/35 pt-4">\n                  <button\n                    type="submit"\n                    className="border border-[rgb(var(--sep-colour-8d6d3e))] bg-[rgb(var(--sep-colour-332719))] px-4 py-2 text-[9px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-efd9aa))]"\n                  >\n                    Save ownership\n                  </button>\n                </div>\n              </form>\n            );\n          },\n        )}\n\n        {cosmetics.length === 0 ? (\n          <div className="bg-[rgb(var(--sep-colour-17110d))] p-6 text-[11px] leading-5 text-[rgb(var(--sep-colour-8f8271))] lg:col-span-2">\n            No active Sheet Frame or\n            Chat Frame cosmetics exist\n            yet. Create one in\n            /admin/cosmetics first.\n          </div>\n        ) : null}\n      </div>\n    </section>\n  );\n}\n',
}
for rel, content in new_files.items():
    path = ROOT / rel
    if path.exists():
        raise SystemExit(f'{rel} already exists; stop.')
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding='utf-8')

